// Generated by scripts/sync-valuation.py from shared/valuation/service.js as rp-valuation-service.js; edit the shared source.
// Explicit service entry for the empire-wide settlement-point snapshot.
// This is the only cross-mod value entry: all adapters use the same scope and
// key, so the same player/save/cache computes once. The pure settlement model
// remains independent of globalThis; importing this file does not create a
// cache until a function is called.

import {getSharedValuationCache, INVALIDATION_REASONS} from './rp-valuation-cache.js';
import {createSettlementPointSnapshot} from './rp-valuation-settlement.js';

export const SETTLEMENT_POINTS_SCOPE = 'settlement-points';
export const SETTLEMENT_POINTS_KEY = 'settlement-points';

function sessionFor({playerId, saveId, cache = getSharedValuationCache()}) {
  if (playerId === undefined || playerId === null) throw new Error('settlementPointSnapshot requires playerId');
  if (saveId === undefined || saveId === null || saveId === '') throw new Error('settlementPointSnapshot requires saveId');
  return cache.context({playerId, saveId, scope: SETTLEMENT_POINTS_SCOPE});
}

// The input must contain playerId/saveId for isolation. A changed input does
// not silently replace a cached snapshot: call invalidateSettlementPointSnapshot
// (or use the explicit invalidation reasons) first. Reading/computing a key
// with a pending invalidation inside a batch throws ValuationCacheStaleError.
export function settlementPointSnapshot(input = {}, {cache, key = SETTLEMENT_POINTS_KEY} = {}) {
  const {playerId, saveId, ...snapshotInput} = input;
  const session = sessionFor({playerId, saveId, cache});
  // Never cache invalid/not-estimated snapshots: a later complete input must be
  // able to recompute instead of being masked by a permanently bad entry.
  return session.getOrCompute(
    key,
    () => createSettlementPointSnapshot({...snapshotInput, playerId, saveId}),
    {cacheable: snapshot => snapshot.status !== 'invalid' && snapshot.status !== 'not-estimated'}
  );
}

// Re-loading the same save, or any explicit snapshot replacement, must call
// this. It is deliberately not automatic: the caller owns the event timing.
export function invalidateSettlementPointSnapshot({
  playerId,
  saveId,
  cache,
  key = SETTLEMENT_POINTS_KEY,
  reason = INVALIDATION_REASONS.SNAPSHOT_CREATED
} = {}) {
  const session = sessionFor({playerId, saveId, cache});
  return session.invalidate(reason, {key});
}

export function batchSettlementPointAdjustments({playerId, saveId, cache} = {}, callback) {
  const session = sessionFor({playerId, saveId, cache});
  return session.batch(callback);
}
